#!/usr/bin/env Rscript
# R half of the stochastic network-method status sweep. Inputs are generated by
# run_network_status_stress.py; R records its own subsamples so Python can replay
# exactly the same draws.

args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 3L) {
  stop("Usage: Rscript network_status_stress.R <spieceasi|spring> <cases_dir> <out_dir>")
}
method <- args[[1]]
cases_dir <- args[[2]]
out_dir <- args[[3]]
if (!method %in% c("spieceasi", "spring")) stop("unknown method: ", method)
suppressPackageStartupMessages(library(jsonlite))

if (method == "spieceasi") {
  ref_r <- file.path("spiec-easi-python", "reference", "R")
  suppressWarnings(suppressMessages(pkgload::load_all(ref_r, quiet = TRUE)))
  suppressPackageStartupMessages(library(huge))
} else {
  suppressPackageStartupMessages({
    library(latentcor)
    library(huge)
    library(pulsar)
  })
  spring_r <- file.path("SPRING-master", "R")
  for (file in c("helpers.R", "SPRING.R", "synthData.R")) {
    source(file.path(spring_r, file))
  }
}

write_matrix <- function(x, path) {
  write.table(x, path, sep = ",", row.names = FALSE, col.names = FALSE,
              quote = FALSE)
}
write_vector <- function(x, path) {
  writeLines(sprintf("%.17g", as.numeric(x)), path)
}

case_dirs <- sort(list.dirs(cases_dir, recursive = FALSE, full.names = TRUE))
rows <- vector("list", length(case_dirs))
for (i in seq_along(case_dirs)) {
  dir <- case_dirs[[i]]
  case <- basename(dir)
  p <- jsonlite::fromJSON(file.path(dir, "params.json"))
  x <- as.matrix(read.csv(file.path(dir, "input.csv"), header = FALSE))
  n <- nrow(x)
  nrep <- as.integer(p$rep_num)
  ratio <- 0.8
  size <- floor(n * ratio)
  set.seed(as.integer(p$seed))
  indices <- replicate(nrep, sample(seq_len(n), size, replace = FALSE), simplify = FALSE)
  write_matrix(do.call(rbind, indices), file.path(dir, "r_subsample_indices.csv"))

  lambda_path <- NULL
  set.seed(as.integer(p$seed))
  result <- tryCatch({
    if (method == "spieceasi") {
      fit <- spiec.easi(
        x, method = "mb", sel.criterion = "stars", verbose = FALSE,
        nlambda = 3L, lambda.min.ratio = 0.1, lambda.log = TRUE,
        pulsar.params = list(seed = as.integer(p$seed), rep.num = nrep,
                             thresh = 0.2, subsample.ratio = ratio, ncores = 1L)
      )
      adjacency <- as.matrix(getRefit(fit))
      summary <- as.numeric(fit$select$stars$summary)
      opt_index <- as.integer(getOptInd(fit))
      beta <- as.matrix(getOptBeta(fit))
      lambda_path <- as.numeric(fit$lambda)
    } else {
      qdat <- mclr(x)
      full <- suppressMessages(latentcor::latentcor(
        qdat, types = "tru", method = "approx", tol = 1e-6,
        use.nearPD = TRUE, nu = 0.001, ratio = 0.9, showplot = FALSE
      )$R)
      lmax <- max(max(full - diag(ncol(full))), -min(full - diag(ncol(full))))
      lambda_path <- exp(seq(log(lmax), log(lmax * 0.1), length.out = 3L))
      write_vector(lambda_path, file.path(dir, "r_lambda_path.csv"))
      fit <- SPRING(
        x, quantitative = FALSE, lambda.min.ratio = 0.1, nlambda = 3L,
        lambdaseq = lambda_path, seed = as.integer(p$seed), ncores = 1L,
        thresh = 0.2, subsample.ratio = ratio, rep.num = nrep,
        Rtol = 1e-6, verbose = FALSE, Rmethod = "approx",
        use.nearPD = TRUE, nu = 0.001, ratio = 0.9
      )
      stars <- fit$output$stars
      adjacency <- as.matrix(fit$fit$refit$stars)
      summary <- as.numeric(stars$summary)
      opt_index <- as.integer(stars$opt.index)
      beta <- as.matrix(fit$fit$est$beta[[opt_index]])
      summary <- as.numeric(stars$summary)
    }
    write_matrix(adjacency, file.path(dir, "r_adjacency.csv"))
    write_matrix(beta, file.path(dir, "r_beta_selected.csv"))
    write_vector(summary, file.path(dir, "r_stability.csv"))
    write_vector(lambda_path, file.path(dir, "r_lambda_path.csv"))
    is_finite <- all(is.finite(summary)) && all(is.finite(adjacency)) &&
      all(is.finite(beta)) && length(opt_index) == 1L && is.finite(opt_index)
    list(status = if (is_finite) "finite" else "nonfinite", error = "",
         opt_index = opt_index)
  }, error = function(e) {
    list(status = "error", error = conditionMessage(e), opt_index = NA_integer_)
  })
  rows[[i]] <- data.frame(
    case = case,
    status = result$status,
    opt_index = result$opt_index,
    error = result$error,
    stringsAsFactors = FALSE
  )
}
utils::write.csv(do.call(rbind, rows), file.path(out_dir, "r_status.csv"),
                 row.names = FALSE, na = "")
